package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionBuilder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class OptionBuilder_create_TriageGen2Test {

    @Before
    public void setup() {
        OptionBuilder.reset();
    }

    @Test
    public void testCreateWithValidOption() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt);

        // Then
        assertEquals("a", option.getLongOpt());
        assertEquals(false, option.isRequired());
        assertEquals(false, option.hasOptionalArg());
        assertEquals(0, option.getArgs());
        assertEquals(String.class, option.getType());
        assertEquals(",", option.getValueSeparator());
        assertEquals("a", option.getArgName());
    }

    @Test
    public void testCreateWithLongOpt() {
        // Given
        String opt = "a";
        String longOpt = "A";

        // When
        Option option = OptionBuilder.create(opt).withLongOpt(longOpt).create();

        // Then
        assertEquals(longOpt, option.getLongOpt());
    }

    @Test
    public void testCreateWithRequired() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).isRequired().create();

        // Then
        assertEquals(true, option.isRequired());
    }

    @Test
    public void testCreateWithOptionalArg() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).hasOptionalArg().create();

        // Then
        assertEquals(true, option.hasOptionalArg());
    }

    @Test
    public void testCreateWithArgs() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).hasArgs().create();

        // Then
        assertEquals(1, option.getArgs());
    }

    @Test
    public void testCreateWithType() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).withType(String.class).create();

        // Then
        assertEquals(String.class, option.getType());
    }

    @Test
    public void testCreateWithValueSeparator() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).withValueSeparator(',').create();

        // Then
        assertEquals(',', option.getValueSeparator());
    }

    @Test
    public void testCreateWithArgName() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).withArgName("b").create();

        // Then
        assertEquals("b", option.getArgName());
    }

    @Test
    public void testCreateWithDescription() {
        // Given
        String opt = "a";

        // When
        Option option = OptionBuilder.create(opt).withDescription("desc").create();

        // Then
        // There is no way to assert the description of the option
    }

    @Test
    public void testCreateWithInvalidOption() {
        // Given
        String opt = "a";

        // When
        assertThrows(IllegalArgumentException.class, () -> OptionBuilder.create((char) 1));

        // Then
        // The test passes if no exception is thrown
    }
}
